def _fget(name: str) -> List[float]:
    for n, v in FEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _sget(name: str) -> List[str]:
    for n, v in SEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _flat(got) -> List[float]:
    g = List[float]()
    a = np.asarray(got, dtype=float).ravel()
    for i in range(a.shape[0]):
        g.append(float(a[i]))
    return g


def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-15):
    want = _fget(name)
    g = _flat(got)
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if np.isnan(want[i]):
                if not np.isnan(g[i]):
                    ok = False
            elif abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g[:12], want[:12], len(g), len(want))


def checks(name: str, got):
    want = _sget(name)
    g = [str(v) for v in got]
    if g != want:
        print("TEST FAILED:", name, g, want)



def V(x):
    return x.__val__()


def mk(nch: int, n: int, k: float):
    out = np.empty((nch, n))
    for i in range(nch):
        for j in range(n):
            out[i, j] = np.sin(0.05 * (i + 1) * j + k) + 0.3 * np.cos(0.31 * j * (i + 2) + 0.5 * i) + 0.2 * np.sin(2.0 * j)
    return out


names = ['Fp1', 'Fz', 'Cz', 'Pz', 'O1', 'O2']
sf = 100.0
data = mk(6, 1500, 0.3) * 1e-5
raw = mne.io.RawArray(data, mne.create_info(names, sf, 'eeg'))
ev = np.array([[100, 0, 1], [200, 0, 2], [300, 0, 1], [400, 0, 2], [500, 0, 1], [600, 0, 1], [700, 0, 2], [800, 0, 1], [900, 0, 1], [1000, 0, 1]])
ep = mne.Epochs(raw, ev, tmin=-0.2, tmax=0.5, baseline=None, preload=True)

# equalize_event_counts: truncate / mintime / random
e1 = ep.copy()
e1.equalize_event_counts(['1', '2'], method='truncate')
check("eq_trunc_n", [len(e1)])
check("eq_trunc_sel", e1.selection)
e2 = ep.copy()
e2.equalize_event_counts(['1', '2'], method='mintime')
check("eq_mint_sel", e2.selection)
e3 = ep.copy()
e3.equalize_event_counts(['1', '2'], method='random', random_state=5)
check("eq_rand_sel", e3.selection)

# drop_bad with reject_tmin/tmax
data2 = data.copy()
data2[1, 300 + 30] += 4e-4
raw2 = mne.io.RawArray(data2, mne.create_info(names, sf, 'eeg'))
ep2 = mne.Epochs(raw2, ev, tmin=-0.2, tmax=0.5, baseline=None, preload=True, reject_tmin=-0.1, reject_tmax=0.1)
ep2.drop_bad(reject={'eeg': 2e-4})
check("rej_win_sel", ep2.selection)
ep3 = mne.Epochs(raw2, ev, tmin=-0.2, tmax=0.5, baseline=None, preload=True, reject_tmin=0.2, reject_tmax=0.4)
ep3.drop_bad(reject={'eeg': 2e-4})
check("rej_win2_sel", ep3.selection)
ep4 = mne.Epochs(raw2, ev, tmin=-0.2, tmax=0.5, baseline=None, preload=True, reject={'eeg': 2e-4})
check("rej_direct_sel", ep4.selection)

# set_eeg_reference on epochs
e5 = ep.copy()
e5.set_eeg_reference('average')
check("ep_avgref", e5.get_data()[2, :, 5:7], 1e-9, 1e-15)
e6 = ep.copy()
e6.set_eeg_reference(['Cz', 'Pz'])
check("ep_chref", e6.get_data()[2, :, 5:7], 1e-9, 1e-15)

# apply_function
e7 = ep.copy()
e7.apply_function(lambda x: x * 2.0 + 1.0)
check("ep_apply", e7.get_data()[3, :, 4:6], 1e-9, 1e-15)
e8 = ep.copy()
e8.apply_function(lambda x: x - x.mean(axis=-1, keepdims=True), channel_wise=False)
check("ep_apply_all", e8.get_data()[3, :, 4:6], 1e-9, 1e-15)

# Evoked: detrend, apply_function, combine, grand_average
evk = ep['1'].average()
d1 = evk.copy().detrend(1)
check("ev_detrend1", d1.data[:, 3:6], 1e-9, 1e-15)
d0 = evk.copy().detrend(0, picks=['Cz'])
check("ev_detrend0", d0.data[:, 3:6], 1e-9, 1e-15)
evk2 = ep['2'].average()
cn = mne.combine_evoked([evk, evk2], weights='nave')
check("comb_nave", [cn.nave, cn.data[0, 5], cn.data[3, 9]], 1e-9, 1e-15)
checks("comb_nave_c", [cn.comment])
ce = mne.combine_evoked([evk, evk2], weights='equal')
check("comb_eq", [round(ce.nave), ce.data[0, 5], ce.data[3, 9]], 1e-9, 1e-15)
checks("comb_eq_c", [ce.comment])
cw = mne.combine_evoked([evk, evk2], weights=[1.0, -1.0])
check("comb_w", [round(cw.nave), cw.data[0, 5]], 1e-9, 1e-15)
checks("comb_w_c", [cw.comment])
ga = mne.grand_average([evk, evk2])
check("ga", [ga.nave, ga.data[0, 5], ga.data[3, 9]], 1e-9, 1e-15)
checks("ga_c", [ga.comment])
ea = evk.copy()
ea.apply_function(lambda x: x ** 2)
check("ev_apply", ea.data[:, 4:6], 1e-9, 1e-15)
